const names=['Alex Morgan','Sam Chen','Casey Park','Jordan Lee','Riley Quinn','Taylor Reed','Jamie Fox','Cameron Ellis'];
let rounds=[],selectedRound=0,tab='Rounds',editing=null,finalised=false;
function reset(){let ring=[...names.keys()];rounds=[];for(let r=0;r<7;r++){rounds.push(Array.from({length:4},(_,i)=>({a:ring[i],b:ring[7-i],result:null,reason:''})));ring=[ring[0],ring[7],...ring.slice(1,7)]}rounds[0][0].result='a';rounds[0][1].result='draw';rounds[0][2].result='b';selectedRound=0;finalised=false;render()}
const app=document.querySelector('#app');const initials=n=>n.split(' ').map(x=>x[0]).join('');const identity=i=>`<span class="identity"><span class="avatar">${initials(names[i])}</span>${names[i]}</span>`;
const matches=()=>rounds.flat();const resolved=()=>matches().filter(m=>m.result).length;
function ranking(){let rows=names.map((name,i)=>({name,i,points:0,played:0,wins:0,draws:0}));matches().forEach(m=>{if(!m.result)return;rows[m.a].played++;rows[m.b].played++;if(m.result==='draw'){rows[m.a].points++;rows[m.b].points++;rows[m.a].draws++;rows[m.b].draws++}else{let w=rows[m[m.result]];w.points+=3;w.wins++}});return rows.sort((a,b)=>b.points-a.points||a.name.localeCompare(b.name))}
function standings(full=false){let last=null,rank=0;return `<div class="panel"><div class="panelheader"><h2>${finalised?'Final':'Provisional'} standings</h2><p class="muted">Effective results only · 3 / 1 / 0</p></div><div class="tablewrap"><table><thead><tr><th class="numeric">Rank</th><th>Player</th>${full?'<th class="numeric">Played</th><th class="numeric">Won</th><th class="numeric">Drawn</th>':''}<th class="numeric">Pts</th></tr></thead><tbody>${ranking().map((r,i)=>{if(r.points!==last){rank=i+1;last=r.points}return `<tr><td class="numeric">${rank}</td><td>${r.name}</td>${full?`<td class="numeric">${r.played}</td><td class="numeric">${r.wins}</td><td class="numeric">${r.draws}</td>`:''}<td class="numeric"><b>${r.points}</b></td></tr>`}).join('')}</tbody></table></div><p class="footnote">Equal points share a position. Names only determine display order.</p></div>`}
function matchTable(readonly=false){const outcome=m=>m.result?`<span class="tag good">${m.result==='draw'?'Draw':names[m[m.result]]+' wins'}</span>`:'<span class="tag wait">Awaiting result</span>';const action=(m,i)=>readonly||finalised?`<span class="muted">${m.result?'Resolved':'Scheduled'}</span>`:`<button class="${m.result?'quiet':'secondary'}" data-match="${i}" aria-label="${m.result?'Correct':'Enter'} result for ${names[m.a]} versus ${names[m.b]}">${m.result?'Correct result':'Enter result'}</button>`;return `<div class="panel tablewrap desktop-matches"><table><thead><tr><th>Table</th><th>Match</th><th>Outcome</th><th class="action-col">${readonly?'Status':'Action'}</th></tr></thead><tbody>${rounds[selectedRound].map((m,i)=>`<tr class="${m.result?'':'pending-row'}"><td>${String(i+1).padStart(2,'0')}</td><td><div class="pairing">${identity(m.a)}<span class="versus">vs</span>${identity(m.b)}</div></td><td>${outcome(m)}</td><td class="action-col">${action(m,i)}</td></tr>`).join('')}</tbody></table></div><div class="mobile-matches">${rounds[selectedRound].map((m,i)=>`<article class="match-card"><div class="match-meta">Table ${String(i+1).padStart(2,'0')} · Round ${selectedRound+1}</div><div class="pairing">${identity(m.a)}<span class="versus">vs</span>${identity(m.b)}</div><div class="actions">${outcome(m)}${action(m,i)}</div></article>`).join('')}</div>`}
function roundContent(readonly=false){const pending=rounds[selectedRound].filter(m=>!m.result).length;const next=rounds[selectedRound].findIndex(m=>!m.result);return `<div class="round-picker"><span class="eyebrow">PUBLISHED ROUNDS</span><div class="rounds" aria-label="Select round">${rounds.map((_,i)=>`<button data-round="${i}" class="${i===selectedRound?'active':''}" aria-label="Round ${i+1}" aria-pressed="${i===selectedRound}">${i+1}</button>`).join('')}</div></div><div class="grid"><section><div class="sectionhead round-heading"><div><h2>Round ${selectedRound+1}</h2><p class="round-summary">${pending?`${pending} ${pending===1?'match needs':'matches need'} a result`:'All matches resolved'} <span>· ${4-pending} of 4 complete</span></p></div>${!readonly&&!finalised&&next>=0?`<button class="primary" data-match="${next}">Record next result</button>`:''}</div>${finalised?'<p class="notice">Competition finalised. Results are read-only.</p>':''}${matchTable(readonly)}<p class="round-help">${readonly?'Published matches · Europe/Madrid':'All rounds are published. Record matches in the order they finish.'}</p></section>${standings()}</div>`}
function admin(){app.innerHTML=`<div class="shell"><aside><a class="brand" href="#admin">HERALD<em>.</em></a><div class="org">Northside Gaming<small>Organisation workspace</small></div><div class="rail active">▦ &nbsp; Tournaments</div><div class="profile"><span class="avatar">JF</span><div>Julio Fuentes<small style="display:block;color:#aeb6c0">Tournament director</small></div></div></aside><main><div class="crumb">Workspace / Tournaments / Saturday Open</div><header class="top"><div><h1>Saturday Open</h1><div class="muted">Individual · Round-robin · Madrid · 7 Nov 2026, 10:00 CET</div><div class="tags"><span class="tag">Published</span><span class="tag">Registration closed</span><span class="tag live">${finalised?'Finalised':'Running'}</span></div></div><button onclick="location.hash='public/saturday'">Public view ↗</button></header><nav class="tabs" aria-label="Tournament sections">${['Overview','Entries','Rounds','Standings'].map(t=>`<button data-tab="${t}" class="${tab===t?'active':''}" aria-current="${tab===t?'page':'false'}">${t}</button>`).join('')}</nav>${tab==='Rounds'?roundContent():tab==='Standings'?standings(true):tab==='Entries'?`<div class="sectionhead"><h2>Entries</h2><span class="tag">8 of 8 places</span></div><div class="panel tablewrap"><table><thead><tr><th>Player</th><th>Admission</th><th>Check-in</th></tr></thead><tbody>${names.map((n,i)=>`<tr><td>${identity(i)}</td><td>Admitted</td><td><span class="tag good">Confirmed</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="statrow"><div class="panel stat">Admitted entrants<strong>8 <small>/ 8</small></strong></div><div class="panel stat">Resolved matches<strong>${resolved()} <small>/ 28</small></strong></div><div class="panel stat">Published rounds<strong>7</strong></div></div><div class="panel panelheader summary"><h2>A clear path to the final table.</h2><p class="muted">Every entrant plays every other entrant once. Record each outcome, review the standings and finalise when all 28 matches are resolved.</p><ul><li>Win: 3 points · Draw: 1 point · Loss: 0 points</li><li>Equal points result in shared positions.</li><li>Individual entries need no rosters or lineups.</li></ul><p class="notice">${finalised?'Final standings published.':`${28-resolved()} matches remain before finalisation.`}</p><button id="finalise" class="primary" ${resolved()!==28||finalised?'disabled':''}>${finalised?'Finalised':'Finalise tournament'}</button><p></p></div>`}<p class="muted prototype-footer">HERALD / NORTHSIDE GAMING &nbsp; · &nbsp; Frontend concept</p></main></div>`;bind()}
const events=[{id:'saturday',name:'Saturday Open',type:'Individual',game:'Strategy',date:'7 Nov · 10:00 CET',place:'Madrid, Spain',slots:'8 of 8 places',status:'Registration closed',code:'01'}, {id:'friday',name:'Friday Night Duel',type:'Individual',game:'Card games',date:'13 Nov · 18:30 CET',place:'Madrid, Spain',slots:'8 of 16 places',status:'Registration open',code:'02'}, {id:'arena',name:'Weekend Arena Cup',type:'Teams',game:'Team competition',date:'14 Nov · 16:00 CET',place:'Online',slots:'6 of 8 teams',status:'Registration open',code:'03'}];
const publicNav=()=>`<nav class="publicnav"><a class="brand" href="#discover">HERALD<span style="color:var(--volt)">.</span></a><div class="links"><a href="#discover">Tournaments</a><button onclick="location.hash='admin'">Organiser workspace ↗</button></div></nav>`;
function cards(){let q=document.querySelector('#search').value.toLowerCase(),type=document.querySelector('#type').value,place=document.querySelector('#place').value;let filtered=events.filter(e=>e.name.toLowerCase().includes(q)&&(!type||e.type===type)&&(!place||(e.place==='Online')===(place==='Online')));document.querySelector('#count').textContent=`${filtered.length} tournaments`;document.querySelector('#cards').innerHTML=filtered.map(e=>`<article class="panel"><div class="cover cover-${e.id}"><span class="tag ${e.status==='Registration open'?'good':''}">${e.status}</span><strong>${e.game}</strong></div><div class="cardbody"><h2>${e.name}</h2><p>${e.game} · ${e.type}</p><p class="event-date">${e.date}</p><p>${e.place}</p><div class="actions"><small>${e.slots}</small><button onclick="location.hash='public/${e.id}'">View tournament ↗</button></div></div></article>`).join('')||'<div class="empty"><h3>No tournaments found</h3><p class="muted">Try another name or broaden your filters.</p><button id="clear">Clear filters</button></div>';document.querySelector('#clear')?.addEventListener('click',()=>{document.querySelector('#search').value='';document.querySelector('#type').value='';document.querySelector('#place').value='';cards()})}
function discover(){app.innerHTML=publicNav()+`<header class="hero"><div><div class="eyebrow">FIND YOUR COMPETITION</div><h1>Your next match<br>starts here.</h1><p>Local rivals. New challenges. Your place in the game.</p><button class="primary" onclick="document.querySelector('#events').scrollIntoView()">Explore tournaments ↓</button></div><div class="art" aria-hidden="true"><strong>PLAY.</strong></div></header><main class="publicbody" id="events"><div class="sectionhead"><h2>Find your next tournament</h2><span id="count" class="muted"></span></div><div class="filters"><label class="search-field" for="search">Search tournaments<input id="search" aria-label="Search tournaments" placeholder="Search by name…"></label><label for="type">Entry type<select id="type" aria-label="Entry type"><option value="">Individuals & teams</option><option>Individual</option><option>Teams</option></select></label><label for="place">Location<select id="place" aria-label="Location"><option value="">Online & in person</option><option>Online</option><option>In person</option></select></label></div><div class="cards" id="cards"></div></main>`;['search','type','place'].forEach(id=>document.getElementById(id).addEventListener('input',cards));cards()}
function detail(id){let e=events.find(e=>e.id===id)||events[0];app.innerHTML=publicNav()+`<main class="publicbody"><button class="detailback" onclick="location.hash='discover'">← All tournaments</button><header class="top"><div><div class="eyebrow">NORTHSIDE GAMING PRESENTS</div><h1>${e.name}</h1><p class="muted">${e.game} · ${e.type} · ${e.date} · Europe/Madrid<br>${e.place}</p><div class="tags"><span class="tag">Published</span><span class="tag">${e.status}</span><span class="tag live">${id==='saturday'?finalised?'Finalised':'Running':'Preparing'}</span></div></div><span class="tag">${e.slots}</span></header><section class="wide">${id==='saturday'?roundContent(true):`<div class="panel panelheader summary"><h2>The competition</h2><p>Join a friendly, competitive round-robin event. Every entry plays every other entry once, with 3 points for a win and 1 for a draw.</p>${e.type==='Teams'?'<p>Direct 5v5 · 5 starters · Up to 2 reserves. One team occupies one place. Eligible lineups are required before each match.</p>':'<p>Individual entry · One player per side.</p>'}<p class="notice">Registration is shown for design review. Sign-in and applications are outside this prototype.</p></div>`}</section></main>`;bind()}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;admin()});document.querySelectorAll('[data-round]').forEach(b=>b.onclick=()=>{selectedRound=+b.dataset.round;render()});document.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>openResult(+b.dataset.match));document.querySelector('#finalise')?.addEventListener('click',()=>{if(resolved()===28&&confirm('Publish the final standings? Results will become read-only in this demo.')){finalised=true;render();toast('Final standings published')}})}
function openResult(i) {
  editing = rounds[selectedRound][i];
  document.querySelector('#matchTitle').textContent = names[editing.a] + ' vs ' + names[editing.b];
  document.querySelector('#outcome').innerHTML = `<option value="" disabled>Select outcome</option><option value="a">${names[editing.a]} wins</option><option value="draw">Draw</option><option value="b">${names[editing.b]} wins</option>`;
  document.querySelector('#outcome').value = editing.result || '';
  document.querySelector('#reason').value = '';
  document.querySelector('#reason').required = !!editing.result;
  document.querySelector('#correctionFields').hidden = !editing.result;
  preview();
  document.querySelector('#result').showModal();
}
function preview() {
  const next = document.querySelector('#outcome').value;
  const selected = ['a', 'draw', 'b'].includes(next);
  document.querySelector('#confirmResult').disabled = !selected;
  if (!selected) {
    document.querySelector('#preview').innerHTML = '<p class="selection-help">No result selected. Choose the observed outcome to review its points before confirming.</p>';
    return;
  }
  const label = v => !v ? 'No effective result' : v === 'draw' ? 'Draw' : names[editing[v]] + ' wins';
  const pts = (v, side) => !v ? 0 : v === 'draw' ? 1 : v === side ? 3 : 0;
  document.querySelector('#preview').innerHTML = `<div class="impact-heading">Result review</div><div class="impact-outcomes"><div><span>Previous</span><strong>${label(editing.result)}</strong></div><div><span>New outcome</span><strong>${label(next)}</strong></div></div><div class="impact-points">${['a', 'b'].map(side => `<div><span>${names[editing[side]]}</span><strong>${pts(editing.result, side)} → ${pts(next, side)} pts</strong></div>`).join('')}</div><p>Points for this match only. ${editing.result ? 'The previous points will be replaced.' : 'Standings update when you confirm.'}</p>`;
}
document.querySelector('#outcome').onchange = preview;
document.querySelector('#cancel').onclick = () => document.querySelector('#result').close();
document.querySelector('#resultForm').onsubmit = event => {
  event.preventDefault();
  const outcome = document.querySelector('#outcome').value;
  if (!['a', 'draw', 'b'].includes(outcome) || !event.currentTarget.reportValidity()) return;
  editing.result = outcome;
  editing.reason = document.querySelector('#reason').value;
  document.querySelector('#result').close();
  render();
  toast('Result recorded · Standings updated');
};
function toast(message) {
  const target = document.querySelector('#toast');
  target.textContent = message;
  target.style.display = 'block';
  setTimeout(() => target.style.display = 'none', 3200);
}
function render(){let route=location.hash.slice(1);if(route==='discover')discover();else if(route.startsWith('public/'))detail(route.split('/')[1]);else admin()}
window.onhashchange=render;document.querySelector('#reset').onclick=()=>{reset();toast('Demo reset')};reset();
